select ifnull(sum(total_amount_cent),0)
from ticket_order
where scenic_id=#{scenicId}
  and created_at between #{start} and #{end}
  and status in ('PAID','USED','REFUNDING','RESCHEDULING','RESCHEDULED')

select count(1)
from ticket_order
where scenic_id=#{scenicId}
  and created_at between #{start} and #{end}
  and status in ('PAID','USED','REFUNDING','RESCHEDULING','RESCHEDULED')
